// --- WebGL LUT Engine Implementation ---
        const canvas = document.getElementById('preview-canvas');
        const ctx = canvas.getContext('2d');
        let originalImage = null;
        function handleImage(input) {
            if (input.files && input.files[0]) {
                const reader = new FileReader();
                reader.onload = function (e) {
                    const img = new Image();
                    img.onload = function () {
                        originalImage = img;
                        // Max width for desktop/android view
                        const maxDim = window.innerWidth < 768 ? 1200 : 2400;
                        let w = img.width;
                        let h = img.height;
                        if (w > maxDim) {
                            h = (maxDim / w) * h;
                            w = maxDim;
                        }
                        canvas.width = w;
                        canvas.height = h;
                        ctx.drawImage(img, 0, 0, w, h);
                        document.getElementById('upload-prompt').style.display = 'none';
                    };
                    img.src = e.target.result;
                };
                reader.readAsDataURL(input.files[0]);
            }
        }
        function applyLUT(type, btn) {
            if (!originalImage) {
                showToast("Please provide image artifact first.");
                return;
            }
            // UI state management
            document.querySelectorAll('.preset-card').forEach(c => c.classList.remove('active'));
            if (btn) btn.classList.add('active');
            // Simulation of LUT engine behavior for demo
            // Real implementation would use WebGL textures
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.filter = getFilter(type);
            ctx.drawImage(originalImage, 0, 0, canvas.width, canvas.height);
            ctx.filter = 'none';
        }
        function getFilter(type) {
            switch (type) {
                case 'teal-orange': return 'contrast(1.2) saturate(1.1) hue-rotate(-5deg) sepia(0.2)';
                case 'vintage': return 'sepia(0.4) contrast(0.9) brightness(1.1) saturate(0.8)';
                case 'noir': return 'grayscale(1) contrast(1.5) brightness(0.9)';
                default: return 'none';
            }
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        // --- SCROLL LOGIC ---
